// Direct-navigation explainer (ADR 0020 #8). Lists HIDE blocked-org PRs, but an
// explicit deep link / stale notification to one must EXPLAIN — never a 404.
// Same role-aware CTAs as the Settings org card (via OrgPlanActions), so a user
// meets one consistent explanation wherever the gate catches them.
//
// Renders the centered explainer only — the app Shell already provides the
// window chrome + icon rail around this Outlet (the design mock drew them just
// so the canvas could show a standalone artboard).

import { ArrowLeft, Building2, Lock, Settings } from 'lucide-react';
import { useNavigate } from '@tanstack/react-router';
import { INBOX_DEFAULTS } from '../router/search';
import { useOrgAccess } from '../screens/settings/orgs/useOrgAccess';
import { OrgPlanActions } from './OrgPlanActions';
import { useEffect } from 'react';
import { track, Events } from '../observability';

// Padlocked org tile — neutral monogram + a padlock badge (the lock motif).
function LockedOrgTile({ login }: { login: string }) {
  const letter = (login.replace(/[^a-z0-9]/gi, '').charAt(0) || '?').toUpperCase();
  return (
    <div className="relative size-16">
      <div className="flex size-16 items-center justify-center rounded-2xl bg-muted text-[26px] font-bold text-muted-foreground ring-1 ring-border">
        {letter}
      </div>
      <div className="absolute -bottom-1.5 -right-1.5 flex size-[26px] items-center justify-center rounded-full bg-card ring-1 ring-border">
        <Lock className="size-3.5 text-foreground" />
      </div>
    </div>
  );
}

export function BlockedOrgScreen({ owner }: { owner: string }) {
  const navigate = useNavigate();
  const { installed, isLoading } = useOrgAccess();
  const acct = installed.find(
    (a) => a.account.login.toLowerCase() === owner.toLowerCase(),
  );
  // A paid-but-full org has a plan — the ask is a seat, not a trial (ADR 0020).
  const seatsFull = acct?.plan.tier === 'seats-full';
  const eyebrow = seatsFull ? 'Organization seats full' : 'Organization needs a plan';
  const title = seatsFull ? `${owner}'s seats are full` : `${owner} needs a plan`;

  // Conversion signal: a user hit a hard org gate via deep link (ADR 0021).
  // Fires once the access check resolves, with the reason that drives the CTA.
  const blockedOrgId = acct?.account.id ?? null;
  useEffect(() => {
    if (isLoading) return;
    track(
      Events.OrgBlockedHit,
      { owner, reason: seatsFull ? 'seats_full' : 'no_plan' },
      { orgId: blockedOrgId },
    );
  }, [owner, isLoading, seatsFull, blockedOrgId]);

  return (
    <div className="flex flex-1 items-center justify-center bg-panel px-8 py-10">
      <div className="flex w-full max-w-[460px] flex-col items-center text-center">
        {isLoading ? (
          <div className="flex size-16 items-center justify-center rounded-2xl bg-muted text-muted-foreground ring-1 ring-border">
            <Building2 className="size-7" />
          </div>
        ) : (
          <LockedOrgTile login={owner} />
        )}

        <div className="mt-4 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/70">
          {isLoading ? 'Checking access' : eyebrow}
        </div>

        {isLoading ? (
          <div className="mt-2 h-6 w-56 animate-pulse rounded-md bg-muted" />
        ) : (
          <h1 className="mt-2 font-display text-[22px] font-semibold tracking-tight text-foreground">
            {title}
          </h1>
        )}

        <p className="mt-2.5 max-w-[400px] text-[13px] leading-relaxed text-muted-foreground">
          {isLoading ? (
            <>Pyor is confirming whether this organization has a plan. One moment…</>
          ) : seatsFull ? (
            <>
              Pyor is per-organization.{' '}
              <span className="font-medium text-foreground">{owner}</span> is on a paid
              plan, but all its seats are in use — so its pull requests stay hidden for
              you until a seat frees up.
            </>
          ) : (
            <>
              Pyor is per-organization: a seat unlocks one org plus your always-free
              personal account.{' '}
              <span className="font-medium text-foreground">{owner}</span> doesn't have a
              plan yet, so its pull requests stay hidden everywhere in Pyor.
            </>
          )}
        </p>

        <div className="mt-6">
          {isLoading ? (
            <div className="h-10 w-40 animate-pulse rounded-lg bg-muted" />
          ) : (
            <OrgPlanActions
              githubOrgId={acct?.account.id ?? 0}
              login={owner}
              role={acct?.role ?? null}
              reason={seatsFull ? 'seats-full' : 'no-plan'}
              size="screen"
            />
          )}
        </div>

        <div className="mt-7 flex items-center gap-3 text-[12.5px]">
          <button
            type="button"
            onClick={() => void navigate({ to: '/inbox', search: INBOX_DEFAULTS })}
            className="inline-flex items-center gap-1.5 text-muted-foreground hover:text-foreground"
          >
            <ArrowLeft className="size-3.5" /> Back to your inbox
          </button>
          <span className="text-border">·</span>
          <button
            type="button"
            onClick={() => void navigate({ to: '/settings' })}
            className="inline-flex items-center gap-1.5 text-muted-foreground hover:text-foreground"
          >
            <Settings className="size-3.5" /> Manage organizations
          </button>
        </div>
      </div>
    </div>
  );
}
